import { Component } from '@angular/core';
import { Capacitor } from '@capacitor/core';
import { StatusBar, Style } from '@capacitor/status-bar';
import { IonApp, IonRouterOutlet } from '@ionic/angular';

@Component({
  selector: 'app-root',
  templateUrl: 'app.component.html',
  imports: [IonApp, IonRouterOutlet],
})
export class AppComponent {
  constructor() {
    // The status bar only exists on native platforms; calling it on the web
    // rejects with an "unimplemented" error and pollutes the console.
    if (Capacitor.isNativePlatform()) {
      void this.configureStatusBar();
    }
  }

  private async configureStatusBar(): Promise<void> {
    await StatusBar.setOverlaysWebView({ overlay: false });
    await StatusBar.setBackgroundColor({ color: '#f7f8fc' });
    await StatusBar.setStyle({ style: Style.Light });
  }
}
